/**
 * Exam-day attendance. Everybody on an exam's list is PRESENT by default, so only exceptions are stored:
 *  - absent : did not appear
 *  - umc    : unfair-means case (answer book is forwarded separately, listed under (D) on the memo)
 *  - stray  : sat the paper but is not on the exam's list (listed under (E))
 * Marks are keyed by normalized roll number (not student id) so strays fit the same shape and marks
 * survive a student re-import or a regenerated seating plan.
 */
export type AttendanceMark = 'absent' | 'umc' | 'stray';

export interface AttendanceEntry {
  rollNumber: string;
  mark: AttendanceMark;
  /** e.g. "Copying", "Mobile phone" for umc; free text for absent ("Medical") */
  reason?: string;
  note?: string;
  /** Strays only: who they are, since they are not in the student list. */
  name?: string;
  branch?: string;
  markedAt: string;
}

export interface ExamAttendance {
  id: string;
  examId: string;
  entries: Record<string, AttendanceEntry>;
  /** Frozen after the memo is handed over; the UI refuses further edits until unlocked. */
  finalized?: boolean;
  createdAt: string;
  updatedAt: string;
}

export function normalizeRoll(roll: string): string {
  return roll.trim().replace(/\s+/g, '').toUpperCase();
}

/** Institution details printed on the secrecy memo. */
export interface InstitutionProfile {
  university: string;
  universityTagline?: string;
  college: string;
  centreNo: string;
  superintendent?: string;
  /** University emblem as a data URL, printed at the left of the memo header (optional). */
  logo?: string;
}

